pub fn integer_nonzero_decimal_digit_widen(digit: NonZeroDecimalDigit) -> DecimalDigit {
    match digit.clone() {
        NonZeroDecimalDigit::NonZeroD1 => DecimalDigit::D1,
        NonZeroDecimalDigit::NonZeroD2 => DecimalDigit::D2,
        NonZeroDecimalDigit::NonZeroD3 => DecimalDigit::D3,
        NonZeroDecimalDigit::NonZeroD4 => DecimalDigit::D4,
        NonZeroDecimalDigit::NonZeroD5 => DecimalDigit::D5,
        NonZeroDecimalDigit::NonZeroD6 => DecimalDigit::D6,
        NonZeroDecimalDigit::NonZeroD7 => DecimalDigit::D7,
        NonZeroDecimalDigit::NonZeroD8 => DecimalDigit::D8,
        NonZeroDecimalDigit::NonZeroD9 => DecimalDigit::D9,
    }
}

pub fn integer_standard_type_from_width(
    signedness: Signedness,
    bits: BitWidth,
) -> Option<StandardIntegerType> {
    {
        let matches = Rc::new({
            let mut __result = Vec::new();
            for width in integer_standard_integer_type_roster().iter().cloned() {
                if ((integer_standard_integer_type_signedness(width.clone()) == signedness.clone())
                    && (crate::std_measure::bit_width_count(
                        integer_standard_integer_type_width_bits(width.clone()),
                    ) == crate::std_measure::bit_width_count(bits.clone())))
                {
                    __result.push(width);
                }
            }
            __result
        });
        if ((matches.clone().len() as i64) == 1) {
            matches.clone().first().cloned()
        } else {
            std::option::Option::None
        }
    }
}

pub fn integer_bound_decimal_spelling(bound: Rc<IntegerIntervalBound>) -> Option<String> {
    match (*bound.clone()).clone() {
        IntegerIntervalBound::IntegerConcreteZero => Some("0".to_string()),
        IntegerIntervalBound::IntegerPointerWidthBound { .. } => std::option::Option::None,
        IntegerIntervalBound::IntegerConcreteBound {
            sign, magnitude: m, ..
        } => {
            let digits = Rc::new({
                let mut __cons_v = (*m.tail.clone()).clone();
                __cons_v.insert(0, integer_nonzero_decimal_digit_widen(m.lead.clone()));
                __cons_v
            });
            let magnitude = Rc::new({
                let mut __result = Vec::new();
                for digit in digits.iter().cloned() {
                    __result.push(crate::std_nat::decimal_digit_glyph(digit.clone()));
                }
                __result
            })
            .join(&"".to_string());
            Some(match sign.clone() {
                IntegerBoundSign::IntegerBoundNegative => {
                    v1_rt::concat("-".to_string(), magnitude.clone())
                }
                IntegerBoundSign::IntegerBoundNonNegative => magnitude.clone(),
            })
        }
    }
}

#[derive(
    Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize,
)]
#[serde(tag = "_variant")]
pub enum IntegerWidthHostRealization {
    WidthValueFitsHostInt,
    WidthValueNeedsExactRealization,
}

pub fn integer_width_host_realization(
    value: Rc<IntegerIntervalBound>,
) -> IntegerWidthHostRealization {
    match (*int64_interval_spec()).clone() {
        IntegerExtent::BoundedIntegerInterval {
            inclusive_min: lo,
            inclusive_max: hi,
            ..
        } => {
            if ((!integer_interval_bound_is_pointer_width(value.clone())
                && integer_interval_bound_less_or_equal(lo.clone(), value.clone()))
                && integer_interval_bound_less_or_equal(value.clone(), hi.clone()))
            {
                IntegerWidthHostRealization::WidthValueFitsHostInt
            } else {
                IntegerWidthHostRealization::WidthValueNeedsExactRealization
            }
        }
        _ => IntegerWidthHostRealization::WidthValueNeedsExactRealization,
    }
}

